test('D1: ball bounces off the top face of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // row 0 col 0: x [4..76], y [48..68]
  state.ball = { x: 40, y: BRICK_TOP - BALL_R - 1, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  const lost = step(state, DT);
  assert.equal(lost, false);
  assert.equal(brick.alive, false, 'brick must be broken');
  assert.ok(state.ball.vy < 0, 'ball must bounce up');
  assert.equal(state.ball.y, BRICK_TOP - BALL_R, 'ball must end above the brick');
});

test('D2: level-6 ball at dt=50ms tunnels through a brick (discrete detection misses)', () => {
  const state = createState(6); // speed 710
  const brick = state.bricks[0];
  state.ball = { x: 40, y: BRICK_TOP - BALL_R - 0.1, r: BALL_R, vx: 0, vy: ballSpeed(6) };
  step(state, 0.05); // 35.5 px step > 34 px (brick height + ball diameter)
  assert.equal(brick.alive, false, 'brick must be broken');
  assert.ok(state.ball.vy < 0, 'ball must bounce up');
  assert.equal(state.ball.y, BRICK_TOP - BALL_R, 'ball must end above the brick');
});

test('D2: same level-6 trajectory bounces identically at dt=1/60 (dt independence)', () => {
  const state = createState(6);
  const brick = state.bricks[0];
  state.ball = { x: 40, y: BRICK_TOP - BALL_R - 0.1, r: BALL_R, vx: 0, vy: ballSpeed(6) };
  step(state, DT);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vy < 0);
});

test('D3: two bricks overlapped in one pass bounce ONCE — no double inversion', () => {
  const state = createState(1);
  const a = state.bricks[0]; // col 0
  const b = state.bricks[1]; // col 1, seam gap 8 < ball diameter 14
  state.ball = { x: 80, y: BRICK_TOP - BALL_R - 1, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(state, DT);
  assert.equal(a.alive, false);
  assert.equal(b.alive, true, 'only the first-contacted brick breaks');
  assert.ok(state.ball.vy < 0, 'exactly one upward bounce');
  assert.equal(state.ball.y, BRICK_TOP - BALL_R, 'ball must end above the bricks');
});

test('D4: side hit flips vx, not vy', () => {
  const state = createState(1);
  const a = state.bricks[0];
  const b = state.bricks[1];
  state.ball = { x: 80, y: 58, r: BALL_R, vx: -ballSpeed(1), vy: 0 };
  step(state, DT);
  assert.equal(a.alive, false);
  assert.equal(b.alive, true);
  assert.ok(state.ball.vx > 0, 'horizontal velocity must flip');
  assert.equal(state.ball.vy, 0, 'vertical velocity must stay unchanged');
  assert.equal(state.ball.x, a.x + a.w + BALL_R, 'ball pushed to the right of the brick');
});

test('D4: corner hit flips BOTH axes', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = { x: 87, y: 37, r: BALL_R, vx: -ballSpeed(1), vy: ballSpeed(1) };
  step(state, DT); // center crosses (83, 41) = brick corner (76, 48) + r
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vx > 0, 'vx must flip');
  assert.ok(state.ball.vy < 0, 'vy must flip');
  assert.equal(state.ball.x, brick.x + brick.w + BALL_R);
  assert.equal(state.ball.y, BRICK_TOP - BALL_R);
});

test('D5: ball starting inside a brick is pushed out — no vibration', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = { x: 40, y: 58, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(state, DT);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vy < 0, 'must bounce up');
  assert.equal(state.ball.y, BRICK_TOP - BALL_R, 'must be pushed out above the brick');
  const overlapping =
    state.ball.x + state.ball.r > brick.x &&
    state.ball.x - state.ball.r < brick.x + brick.w &&
    state.ball.y + state.ball.r > brick.y &&
    state.ball.y - state.ball.r < brick.y + brick.h;
  assert.equal(overlapping, false, 'ball must be outside the brick after resolution');
});

test('D6: fast ball tunnels through the paddle — swept paddle bounce', () => {
  const state = createState(6); // speed 710
  state.ball = { x: 330, y: PADDLE_Y - BALL_R - 0.1, r: BALL_R, vx: 0, vy: ballSpeed(6) };
  const lost = step(state, 0.05); // 35.5 px step > paddle height 12
  assert.equal(lost, false, 'ball must not be lost');
  assert.ok(state.ball.vy < 0, 'must bounce up off the paddle');
  assert.equal(state.ball.y, PADDLE_Y - BALL_R, 'must end above the paddle');
  assert.ok(state.ball.vx > 0, 'off-center hit gives horizontal velocity');
});

test('D7: center paddle hit keeps a playable angle (no vx = 0)', () => {
  const state = createState(1);
  state.ball = { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 0.1, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(state, DT);
  assert.ok(state.ball.vy < 0, 'must bounce up');
  assert.ok(Math.abs(state.ball.vx) > 0, 'vx must not be zero after a center hit');
});

test('D8: paddle bounce renormalizes to the level speed', () => {
  const state = createState(1);
  state.ball = { x: 368, y: PADDLE_Y - BALL_R - 0.1, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(state, DT); // edge hit: hit = 1
  const speed = Math.hypot(state.ball.vx, state.ball.vy);
  assert.ok(Math.abs(speed - ballSpeed(1)) < 1e-9, `speed ${speed} must equal ${ballSpeed(1)}`);
});

