// Corner-hit tolerance: two slab entry times closer than this are a corner.
const EPS = 1e-9;

// Minimum |hit| on the paddle: keeps the rebound angle playable — a dead-center
// hit must never leave the ball with vx = 0 (it would loop vertically).
const PADDLE_MIN_HIT = 0.2;

// Paddle — swept: bounce when the ball's bottom edge crosses the paddle's
// top between the previous and the current position (a fast ball skips the
// 12 px paddle band in one frame), and also when the paddle has been moved
// over the ball (capture): the ball always exits through the top.
const inPaddleReach = ball.x >= paddle.x - ball.r && ball.x <= paddle.x + paddle.w + ball.r;
const crossesPaddleTop = ball.vy > 0 && prevY + ball.r <= paddle.y && ball.y + ball.r >= paddle.y;
const insidePaddle = ball.y + ball.r >= paddle.y && ball.y - ball.r <= paddle.y + paddle.h;
if (inPaddleReach && (crossesPaddleTop || insidePaddle)) {
  ball.y = paddle.y - ball.r;
  // The rebound angle depends on where the paddle was hit; clamped so a
  // center hit keeps a playable angle (never vx = 0).
  const speed = ballSpeed(state.level);
  let hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
  hit = Math.max(-1, Math.min(1, hit));
  if (Math.abs(hit) < PADDLE_MIN_HIT) hit = Math.sign(hit || 1) * PADDLE_MIN_HIT;
  // Outgoing direction from the hit angle (up to ±60° from vertical),
  // renormalized so the speed after the bounce is the level speed.
  const angle = hit * (Math.PI / 3);
  ball.vx = speed * Math.sin(angle);
  ball.vy = -speed * Math.cos(angle);
  state.combo = 0; // touching the paddle resets the combo
}

