}

// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the ceiling, the paddle and the bricks, plus scoring.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const prevX = ball.x;
  const prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle — swept: bounce when the ball's bottom edge crosses the paddle's
  // top between the previous and the current position (a fast ball skips the
  // 12 px paddle band in one frame), and also when the paddle has been moved
  // over the ball (capture): the ball always exits through the top.
  const inPaddleReach = ball.x >= paddle.x - ball.r && ball.x <= paddle.x + paddle.w + ball.r;
  const crossesPaddleTop = ball.vy > 0 && prevY + ball.r <= paddle.y && ball.y + ball.r >= paddle.y;
  const insidePaddle = ball.y + ball.r >= paddle.y && ball.y - ball.r <= paddle.y + paddle.h;
  if (inPaddleReach && (crossesPaddleTop || insidePaddle)) {
    ball.y = paddle.y - ball.r;
    // The rebound angle depends on where the paddle was hit; clamped so a
    // center hit keeps a playable angle (never vx = 0).
    const speed = ballSpeed(state.level);
    let hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    hit = Math.max(-1, Math.min(1, hit));
    if (Math.abs(hit) < PADDLE_MIN_HIT) hit = Math.sign(hit || 1) * PADDLE_MIN_HIT;
    // Outgoing direction from the hit angle (up to ±60° from vertical),
    // renormalized so the speed after the bounce is the level speed.
    const angle = hit * (Math.PI / 3);
    ball.vx = speed * Math.sin(angle);
    ball.vy = -speed * Math.cos(angle);
    state.combo = 0; // touching the paddle resets the combo
  }

  // Bricks: kill the first brick the ball touched during this pass and
  // bounce off it. The resolution is swept (segment from the previous
  // position) so no brick can be crossed without a bounce, and only ONE
  // contact per pass is resolved so two bricks sharing a seam never cancel
  // their bounces.
  resolveBricks(state, prevX, prevY);

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// Resolves the brick the ball touched during this pass: kills it, scores it,
// bounces the ball off the hit face and pushes it back out of the rectangle.
// Only ONE contact per pass is resolved so that two bricks sharing a seam can
// never cancel each other's bounces (one bounce per pass per axis).
// `prevX`/`prevY` are the ball's position at the start of the pass: the
// resolution is SWEPT along the segment [prev, current] so that a fast ball
// cannot cross a brick without ever overlapping it (no tunneling).
function resolveBricks(state, prevX, prevY) {
  const { ball, bricks } = state;

  // Candidates: every live brick whose expanded box (brick inflated by the
  // ball radius) the ball's trajectory crosses, with the entry time of the
  // first contact and the axis of that contact ('x', 'y', or null = corner).
  let best = null;
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const hit = sweptContact(prevX, prevY, ball.x, ball.y, ball.r, brick);
    if (!hit) continue;
    // Earliest contact wins; among (nearly) simultaneous contacts, a corner
    // (both faces entered at once) takes precedence: it constrains both axes.
    if (!best || hit.t < best.t - EPS || (hit.axis === null && Math.abs(hit.t - best.t) <= EPS)) {
      best = hit;
    }
  }
  if (!best) return;

  const { brick, axis } = best;
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);

  // Push the ball out of the brick and flip the velocity on the hit axis,
  // using the incoming direction to pick the face the ball came from.
  if (axis === 'x') {
    if (ball.vx > 0) {
      ball.x = brick.x - ball.r;
    } else {
      ball.x = brick.x + brick.w + ball.r;
    }
    ball.vx = -ball.vx;
  } else if (axis === 'y') {
    if (ball.vy > 0) {
      ball.y = brick.y - ball.r;
    } else {
      ball.y = brick.y + brick.h + ball.r;
    }
    ball.vy = -ball.vy;
  } else {
    // Corner: both faces touched at once — both axes flip.
    if (ball.vx > 0) {
      ball.x = brick.x - ball.r;
    } else {
      ball.x = brick.x + brick.w + ball.r;
    }
    if (ball.vy > 0) {
      ball.y = brick.y - ball.r;
    } else {
      ball.y = brick.y + brick.h + ball.r;
    }
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  }
}

// Swept contact between the ball trajectory segment (prev → current) and the
// brick's expanded box (brick + ball radius), using the slab method: the time
// the segment enters/exits each axis slab. Returns { brick, t, axis } or null.
//   t     — entry time in [0, 1]; negative when the ball started the pass
//           already overlapping the expanded box (deep penetration).
//   axis  — 'x' | 'y' (the slab entered last = the face crossed first),
//           null when both are entered at the same instant (corner).
function sweptContact(px, py, cx, cy, r, brick) {
  const box = { x: brick.x - r, y: brick.y - r, w: brick.w + 2 * r, h: brick.h + 2 * r };
  const dx = cx - px;
  const dy = cy - py;

  let tNearX, tFarX;
  if (dx === 0) {
    if (px < box.x || px > box.x + box.w) return null;
    tNearX = -Infinity;
    tFarX = Infinity;
  } else {
    const t1 = (box.x - px) / dx;
    const t2 = (box.x + box.w - px) / dx;
    tNearX = Math.min(t1, t2);
    tFarX = Math.max(t1, t2);
  }

  let tNearY, tFarY;
  if (dy === 0) {
    if (py < box.y || py > box.y + box.h) return null;
    tNearY = -Infinity;
    tFarY = Infinity;

[139 more lines in file. Use offset=320 to continue.]

  } else {
    const t1 = (box.y - py) / dy;
    const t2 = (box.y + box.h - py) / dy;
    tNearY = Math.min(t1, t2);
    tFarY = Math.max(t1, t2);
  }

  const tEntry = Math.max(tNearX, tNearY);
  const tExit = Math.min(tFarX, tFarY);
  if (tEntry > tExit || tExit < 0 || tEntry > 1) return null;

  let axis;
  if (tEntry > 0) {
    // The ball entered the box during this pass: the slab entered last is
    // the face it crossed first. Equal entry times = a corner hit.
    if (tNearX > tNearY + EPS) axis = 'x';
    else if (tNearY > tNearX + EPS) axis = 'y';
    else axis = null; // corner
  } else {
    // The ball started the pass inside the expanded box: fall back to the
    // axis of smallest penetration into the brick itself.
    axis = penetrationAxis(cx, cy, r, brick);
  }

  return { brick, t: Math.max(0, tEntry), axis };
}

// The axis of smallest penetration of the ball's box into the brick.
// Returns 'x' | 'y' | null (equal penetration = corner).
function penetrationAxis(cx, cy, r, brick) {
  const penX = Math.min(cx + r - brick.x, brick.x + brick.w - (cx - r));
  const penY = Math.min(cy + r - brick.y, brick.y + brick.h - (cy - r));
  if (penX < penY) return 'x';
  if (penY < penX) return 'y';
  return null;
}

// --- Rendering (DOM): brick collision logic STILL mixed in here ------------

// Main render loop. For each live brick we test collision AND draw in the same
// pass: this is where logic and rendering are entangled.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: drawing only — collision, bounce and scoring happen in step().
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

  // Paddle — color hard-coded instead of using the palette (inconsistency #6).
  ctx.fillStyle = '#00e5ff';
  ctx.fillRect(state.paddle.x, state.paddle.y, state.paddle.w, state.paddle.h);

  // Ball — also hard-coded (#6).
  ctx.fillStyle = '#39ff14';
  ctx.beginPath();
  ctx.arc(state.ball.x, state.ball.y, state.ball.r, 0, Math.PI * 2);
  ctx.fill();

  // HUD
  ctx.fillStyle = palette.text;
  ctx.font = '16px monospace';
  ctx.fillText(`Score ${state.score}`, 12, 24);
  ctx.fillText(`Best ${state.best}`, WIDTH - 110, 24);
  ctx.fillText(`Lives ${state.lives}`, WIDTH / 2 - 30, 24);
}

// --- Boot (browser entry point) --------------------------------------------

// Starts the game: wires up the canvas, the mouse and the animation loop.
// The only function that depends on the DOM; never called on import.
export function boot(doc = document) {
  const canvas = doc.getElementById('game');
  const ctx = canvas.getContext('2d');
  canvas.width = WIDTH;
  canvas.height = HEIGHT;

  const state = createState(1);
  state.best = loadBest(doc.defaultView?.localStorage ?? globalThis.localStorage);
  state.running = true;

  // Glow pass: a coarse offscreen light map, stretched over the field.
  const offscreen = doc.createElement('canvas');
  offscreen.width = GLOW_W;
  offscreen.height = GLOW_H;
  const glow = {
    map: createGlowMap(),
    image: offscreen.getContext('2d').createImageData(GLOW_W, GLOW_H),
  };

  // Move the paddle with the mouse.
  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left - state.paddle.w / 2;
    state.paddle.x = Math.max(0, Math.min(WIDTH - state.paddle.w, x));
  });

  let last = performance.now();
  function loop(now) {
    const dt = Math.min((now - last) / 1000, 0.05);
    last = now;

    if (state.running) {
      const lost = step(state, dt);
      if (lost) {
        state.lives -= 1;
        state.combo = 0;
        if (state.lives <= 0) {
          state.best = saveBest(globalThis.localStorage, state.score);
          Object.assign(state, createState(state.level));
          state.best = loadBest(globalThis.localStorage);
        } else {
          // relaunch the ball
          state.ball = createState(state.level).ball;
        }
      }

      // Level cleared: all bricks broken
      if (state.bricks.every((b) => !b.alive)) {
        state.level += 1;
        state.bricks = makeBricks(state.level);
        state.ball = createState(state.level).ball;
      }
    }

    frame(ctx, state);
    drawGlow(ctx, glow, state, WIDTH, HEIGHT, offscreen);
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);

  return state;
}

