      if (state.bricks.every(b => !b.alive)) { state.level++; state.bricks = makeBricks(state.level); state.ball = createState(state.level).ball; }
      state.paddle.x = Math.max(0, Math.min(640 - 96, state.ball.x - 48));
      const s = Math.hypot(state.ball.vx, state.ball.vy);
      const oob = state.ball.x < state.ball.r - 1e-9 || state.ball.x > 640 - state.ball.r + 1e-9 || !Number.isFinite(state.ball.x) || s === 0;
      worst = Math.max(worst, s);
      if (oob) { console.log('  OUT OF BOUNDS at frame', frames, JSON.stringify(state.ball)); return; }
    }
    console.log('  level', state.level, '| frames', frames, '| lives', state.lives, '| score', state.score, '| max speed', worst.toFixed(1), '| alive', state.bricks.filter(b=>b.alive).length);
  };
  console.log('lvl 1 @60fps:'); sim(1, 1/60, 60000);
  console.log('lvl 10 @60fps:'); sim(10, 1/60, 60000);
  console.log('lvl 10 @30fps:'); sim(10, 1/30, 60000);
  console.log('lvl 10 @20fps:'); sim(10, 1/20, 60000);
});
